class Solution:
    def fourSumCount(self, nums1: List[int], nums2: List[int], nums3: List[int], nums4: List[int]) -> int:
        sum_dict = defaultdict(int)
        for a in nums1:
            for b in nums2:
                sum_dict[-(a + b)] += 1
        count = 0
        for c in nums3:
            for d in nums4:
                count += sum_dict[c + d]
        return count

