class Solution:
    def findMode(self, root: Optional[TreeNode]) -> List[int]:
        if not root:
            return []
        freq = {}
        def bfs(node):
            stack = [node]
            while stack:
                cur = stack.pop()
                freq[cur.val] = freq.get(cur.val, 0) + 1
                if cur.right:
                    stack.append(cur.right)
                if cur.left:
                    stack.append(cur.left)
        bfs(root)
        max_cnt = max(freq.values())
        return [key for key, cnt in freq.items() if cnt == max_cnt]

